ALPHABET = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ'
OFFSET = 1000000          # start high so every code has 4+ characters

def encode(num):
    # repeated division by 62; remainders are the digits, least significant first
    if num == 0:
        return ALPHABET[0]
    digits = []
    while num:
        num, rem = divmod(num, 62)
        digits.append(ALPHABET[rem])
    return ''.join(reversed(digits))

def solution(urls):
    code_of = {}           # url -> code: O(1) "seen before?" check
    out = []
    for url in urls:
        if url not in code_of:
            code_of[url] = encode(len(code_of) + OFFSET)   # i-th new url
        out.append(code_of[url])
    return out
